(null)) OR (PBC_PROD_ID) in(
(#{item.pbcProdId,jdbcType=VARCHAR})
) UNION select PBC_PROD_ID,CCY,MDATE from pbc_col_prd_baseinfo_end_sub where (STATUS = '03' or SEND_STATUS = '03') and (
